INSERT INTO use_cases (id, title, author, created_on, status, problem, position, pain_points_note, map_x, map_y, map_seed) VALUES ('governance-in-testing', 'Governance in Testing', 'Steve Zeller', '2026-11-05', 'locked', 'Regulated companies have to prove that every software change was tested and approved before release. Most test automation doesn''t produce that proof on its own: scripts can be changed by anyone, evidence is collected by hand, and AI-written tests can behave differently from run to run. The result is slow releases, audit findings, or both.', 'Leapwork helps regulated enterprises test with control: standards enforced through review and approval, every test change logged and versioned, and deterministic tests that run the same way every time.', 'Review, approval and role-based access in Flow are Enterprise Edition features.', 840, 360, 9);
INSERT INTO use_case_industries (use_case_id, industry_id, sort, label, drives_need) VALUES ('governance-in-testing', 'public-companies', 1, NULL, 'SOX: auditors sample changes to financial systems and expect proof each was tested and approved before release.');
INSERT INTO use_case_industries (use_case_id, industry_id, sort, label, drives_need) VALUES ('governance-in-testing', 'pharma', 2, NULL, 'GxP: systems used in regulated work must be validated, with documented test evidence and approvals.');
INSERT INTO use_case_industries (use_case_id, industry_id, sort, label, drives_need) VALUES ('governance-in-testing', 'financial-services', 3, NULL, 'Change control and resilience rules: DORA in the EU requires testing changes before release plus end-to-end and performance testing; PCI DSS requires approved, tested changes to card systems.');
INSERT INTO use_case_industries (use_case_id, industry_id, sort, label, drives_need) VALUES ('governance-in-testing', 'healthcare', 4, NULL, 'Patient safety: NHS organizations can''t deploy health IT without clinical safety sign-off; EHR upgrades and migrations need full regression. US HIPAA is about data protection, a weaker driver.');
INSERT INTO use_case_personas (use_case_id, persona_id, sort, descriptor, role_in_deal, cares_about) VALUES ('governance-in-testing', 'qa-leader', 1, NULL, 'Buyer and champion', 'One standard across teams; releases they can sign off.');
INSERT INTO use_case_personas (use_case_id, persona_id, sort, descriptor, role_in_deal, cares_about) VALUES ('governance-in-testing', 'practitioner', 2, NULL, 'Evaluator and daily user', 'Stable tests; less evidence paperwork.');
INSERT INTO use_case_personas (use_case_id, persona_id, sort, descriptor, role_in_deal, cares_about) VALUES ('governance-in-testing', 'validation-lead', 3, NULL, 'Approver; can block the deal', 'Evidence that satisfies FDA and EU rules.');
INSERT INTO use_case_personas (use_case_id, persona_id, sort, descriptor, role_in_deal, cares_about) VALUES ('governance-in-testing', 'erp-owner', 4, NULL, 'Influencer on ERP deals', 'Proof every change was tested and approved.');
INSERT INTO use_case_personas (use_case_id, persona_id, sort, descriptor, role_in_deal, cares_about) VALUES ('governance-in-testing', 'cio', 5, NULL, 'Signs off large deals', 'Audit findings, release risk, cost.');
INSERT INTO use_case_personas (use_case_id, persona_id, sort, descriptor, role_in_deal, cares_about) VALUES ('governance-in-testing', 'cto', 6, NULL, 'Sponsor where engineering reports to a CTO (mainly software companies)', 'Engineering speed, safe AI adoption.');
INSERT INTO pain_points (id, use_case_id, product_id, sort, title, detail, fix) VALUES ('git-flow-1', 'governance-in-testing', 'flow', 1, 'Proving every change was tested and approved.', 'Auditors sample changes and expect a test record and sign-off for each.', 'Versioned tests that move from draft to review to published; only authorized roles can publish.');
INSERT INTO pain_points (id, use_case_id, product_id, sort, title, detail, fix) VALUES ('git-flow-2', 'governance-in-testing', 'flow', 2, 'Gathering audit evidence by hand.', 'SAP teams spend weeks collecting screenshots for SOX.', 'Every run keeps the test version, logs and a video, exportable via API.');
INSERT INTO pain_points (id, use_case_id, product_id, sort, title, detail, fix) VALUES ('git-flow-3', 'governance-in-testing', 'flow', 3, 'Slow, manual validation.', 'GxP tests are run and documented by hand, and the tool itself must be validated.', 'No-code automation across SAP, Oracle, Dynamics, Salesforce and desktop apps; GxP-validated managed service via Pharma IT.');
INSERT INTO pain_points (id, use_case_id, product_id, sort, title, detail, fix) VALUES ('git-play-1', 'governance-in-testing', 'play', 4, 'Playwright tests with no controls.', 'Code-based suites lack approvals, roles and an audit trail.', 'Adds login, roles, scheduling, approvals and audit logs around Playwright.');
INSERT INTO pain_points (id, use_case_id, product_id, sort, title, detail, fix) VALUES ('git-play-2', 'governance-in-testing', 'play', 5, 'AI-written tests that vary run to run.', 'A growing concern for QA leaders adopting AI.', 'AI writes tests from requirements and links each to its source; tests run as fixed code with no AI at runtime.');
INSERT INTO pain_points (id, use_case_id, product_id, sort, title, detail, fix) VALUES ('git-go-1', 'governance-in-testing', 'go', 6, 'Performance testing outside the audit trail.', 'DORA requires performance testing, often run in a separate, ungoverned tool.', 'Performance, load and API testing with role-based access and exportable audit logs.');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'necstgen', 1, 'q-necstgen-word-excel', 'Tests its Salesforce-based quality and lab system in a GxP environment. 110 test flows, 270 fully compliant features, running within 14 days.', 'cs-necstgen', 'Case study');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'us-healthcare-provider', 2, 'q-uhp-crisis', 'Monitors tier-one apps, including EHR, around the clock. 11 apps automated in a year, about 30 workflows each; results feed BI dashboards.', 'cs-healthcare-provider', 'Case study');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'pah-nhs', 3, 'q-pah-maintenance', 'Daily checks across 27 apps used to take 3 people half a day. Release testing cut from a week to 2 hours; 76 tests run daily.', 'cs-nhs-pah', 'NHS one-pager');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'investec', 4, 'q-investec-roi', 'Private bank. Automated 95% of regression and built it into CI/CD. 3–4x faster time to market; tests run 24/7.', 'cs-investec', 'Case study');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'bnp-cardif', 5, 'q-cardif-three-fold', 'Insurer. Automated regression for its policy system. Releases went from quarterly to monthly.', 'cs-bnp-cardif', 'Case study');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'tmf-group', 6, 'q-tmf-quality', 'Dynamics 365 program delivered with partner HSO.', 'pt-hso-tmf', 'Announcement');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'multinational-bank', 7, NULL, 'Tests Oracle HCM Cloud.', 'cs-multinational-bank', 'Case study');
INSERT INTO use_case_customers (use_case_id, customer_id, sort, quote_id, what_they_did, source_id, source_label) VALUES ('governance-in-testing', 'fortune500-fintech', 8, NULL, 'Regression testing for core banking and securities trading.', 'cs-fortune500-fintech', 'Case study');
INSERT INTO use_case_partners (use_case_id, partner_id, sort, why_it_matters) VALUES ('governance-in-testing', 'microsoft', 1, 'Monthly D365 updates each need regression testing before release; D365 Finance is often in SOX scope. Microsoft builds Playwright, so the launch partnership backs Play.');
INSERT INTO use_case_partners (use_case_id, partner_id, sort, why_it_matters) VALUES ('governance-in-testing', 'oracle', 2, 'Oracle Health is a common EHR in healthcare; Fusion is ERP for SOX companies.');
INSERT INTO use_case_partners (use_case_id, partner_id, sort, why_it_matters) VALUES ('governance-in-testing', 'sap', 3, 'SAP finance is the most common SOX testing target.');
INSERT INTO use_case_partners (use_case_id, partner_id, sort, why_it_matters) VALUES ('governance-in-testing', 'salesforce', 4, 'NecstGen runs its GxP quality system on Salesforce.');
INSERT INTO use_case_partners (use_case_id, partner_id, sort, why_it_matters) VALUES ('governance-in-testing', 'google', 5, 'Outside backing for Play with teams adopting AI-assisted testing.');
INSERT INTO use_case_competitors (use_case_id, competitor_id, sort, their_pitch, how_we_win, url) VALUES ('governance-in-testing', 'tricentis', 1, 'Full validation toolchain; Vera adds Part 11 e-signatures and approval routing.', 'One platform instead of three products; faster to stand up without a dedicated center of excellence.', 'https://www.tricentis.com/products/digital-validation-vera');
INSERT INTO use_case_competitors (use_case_id, competitor_id, sort, their_pitch, how_we_win, url) VALUES ('governance-in-testing', 'opkey', 2, 'GxP and Part 11 out of the box; deep in Veeva, Oracle and Workday.', 'Broader coverage beyond packaged ERP: desktop, Citrix, custom web, Salesforce.', 'https://www.opkey.com/compliance');
INSERT INTO use_case_competitors (use_case_id, competitor_id, sort, their_pitch, how_we_win, url) VALUES ('governance-in-testing', 'worksoft', 3, 'SAP and Oracle process testing with SOX evidence.', 'Same process depth, plus coverage outside the ERP core.', 'https://www.worksoft.com/');
INSERT INTO objections (id, use_case_id, sort, objection, response) VALUES ('governance-in-testing-obj-1', 'governance-in-testing', 1, 'We already have a validation tool.', 'Keep it for sign-off. Leapwork automates the testing it documents, across more apps than ERP-only tools.');
INSERT INTO objections (id, use_case_id, sort, objection, response) VALUES ('governance-in-testing-obj-2', 'governance-in-testing', 2, 'The tool itself would need validating.', 'Pharma IT offers Leapwork as a GxP-validated managed service.');
INSERT INTO objections (id, use_case_id, sort, objection, response) VALUES ('governance-in-testing-obj-3', 'governance-in-testing', 3, 'No-code can''t handle our complex apps.', 'Customers run it on SAP, Oracle, Dynamics, Salesforce, Citrix and EHRs. Offer a proof of concept on their hardest process.');
INSERT INTO objections (id, use_case_id, sort, objection, response) VALUES ('governance-in-testing-obj-4', 'governance-in-testing', 4, 'We''ll build governance on Playwright ourselves.', 'Play adds approvals, roles and audit logs to Playwright, so the team doesn''t build and maintain them.');
INSERT INTO objections (id, use_case_id, sort, objection, response) VALUES ('governance-in-testing-obj-5', 'governance-in-testing', 5, 'AI in testing is a compliance risk.', 'AI helps write tests; tests run as fixed steps with no AI at runtime, and each links back to its requirement.');
